import React, { useEffect, useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate, useParams, useNavigate } from 'react-router-dom';
import { authAPI, productAPI } from './services/api';

// Import các component từ thư mục pages
import Login from './pages/Login';
import Register from './pages/Register';

// Component ProductList
const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const controller = new AbortController();
    
    const fetchProducts = async () => {
      try {
        const data = await productAPI.getProducts({ 
          signal: controller.signal 
        });
        setProducts(data);
      } catch (error) {
        console.error('Failed to fetch products:', error);
        setError(error.message || 'Failed to load products');
      } finally {
        setLoading(false);
      }
    };

    fetchProducts();

    return () => controller.abort();
  }, []);

  if (loading) return <div className="loading">Loading products...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="product-list">
      {products.map(product => (
        <div key={product.id} className="product-card">
          <h3>{product.name}</h3>
          <p>${product.price}</p>
          <a href={`/products/${product.id}`}>View Details</a>
        </div>
      ))}
    </div>
  );
};

// Component ProductDetail
const ProductDetail = () => {
  const { id } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const controller = new AbortController();
    
    const fetchProduct = async () => {
      try {
        const data = await productAPI.getProductDetails(id, {
          signal: controller.signal
        });
        setProduct(data);
      } catch (error) {
        console.error('Failed to fetch product:', error);
        setError(error.message || 'Product not found');
        navigate('/products');
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();

    return () => controller.abort();
  }, [id, navigate]);

  if (loading) return <div className="loading">Loading product...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className="product-detail">
      <button onClick={() => navigate(-1)}>Back to Products</button>
      <h1>{product.name}</h1>
      <img src={product.image} alt={product.name} />
      <p>{product.description}</p>
      <p>${product.price}</p>
      <button onClick={() => navigate('/')}>Go to Home</button>
    </div>
  );
};

// Component PrivateRoute
const PrivateRoute = ({ children }) => {
  const [auth, setAuth] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  useEffect(() => {
    const controller = new AbortController();
    
    const checkAuth = async () => {
      try {
        // Sử dụng endpoint chính xác từ backend
        await authAPI.getProfile({ signal: controller.signal });
        setAuth(true);
      } catch (error) {
        setAuth(false);
        setError('Please login to continue');
        navigate('/login', { state: { from: location.pathname } });
      } finally {
        setLoading(false);
      }
    };
    
    checkAuth();

    return () => controller.abort();
  }, [navigate]);

  if (loading) return <div className="loading">Checking authentication...</div>;
  if (error) return <div className="error">{error}</div>;
  return auth ? children : null;
};

// Component chính App
const App = () => {
  return (
    <Router>
      <div className="app-container">
        <header>
          <nav>
            <a href="/">Home</a>
            <a href="/products">Products</a>
            <a href="/login">Login</a>
            <a href="/signup">Register</a>
          </nav>
        </header>

        <main>
          <Routes>
            {/* Public routes */}
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Register />} />
            
            {/* Protected routes */}
            <Route path="/" element={
              <PrivateRoute>
                <ProductList />
              </PrivateRoute>
            } />
            
            <Route path="/products" element={
              <PrivateRoute>
                <ProductList />
              </PrivateRoute>
            } />
            
            <Route path="/products/:id" element={
              <PrivateRoute>
                <ProductDetail />
              </PrivateRoute>
            } />
            
            {/* Redirect unknown paths */}
            <Route path="*" element={<Navigate to="/" />} />
          </Routes>
        </main>

        <footer>
          <p>© 2023 My App</p>
        </footer>
      </div>
    </Router>
  );
};

export default App;
